const initSectionTracking = () => {
    if ('IntersectionObserver' in window) {
        const sections = document.querySelectorAll('article[data-section]');
        if (sections.length === 0) return;

        const observer = new IntersectionObserver(entries => {
            const visibleEntry = entries.find(e => e.isIntersecting);
            if (visibleEntry) {
                updateCurrentNavLink(visibleEntry.target.id);
                window.history.replaceState(null, '', `#${visibleEntry.target.id}`);
            }
        }, { rootMargin: '-50% 0px -50% 0px' });
        sections.forEach(section => observer.observe(section));
    } else {
        updateCurrentNavLink(window.location.hash.slice(1) || 'features');
        window.addEventListener('hashchange', () => {
            const targetId = window.location.hash.slice(1);
            if (targetId) updateCurrentNavLink(targetId);
        });
    }
};

