const fieldValidators = {
    email: (value) => {
        if (!value.includes('@')) return 'Email must include an @ symbol';
        const [localPart, domain] = value.split('@');
        if (localPart.length === 0) return 'Email cannot start with @';
        if (!domain || domain.length === 0) return 'Email requires a domain after @';
        if (!domain.includes('.')) return 'Domain requires a dot (e.g., example.com)';
        const domainParts = domain.split('.');
        if (domainParts.some(part => part.length === 0)) return 'Email has invalid domain format';
        return null;
    },
    name: (value) => {
        if (value.length < 2) return 'Name must be at least 2 characters';
        if (!/^[A-Za-z\s]+$/.test(value)) return 'Name can only contain letters and spaces';
        return null;
    },
    message: (value) => {
        if (value.length < 10) return `Message needs ${10 - value.length} more character(s)`;
        if (value.length > 1000) return `Message exceeds limit by ${value.length - 1000} character(s)`;
        return null;
    }
};

