input.old_string:
const validateField = (field) => {
    if (!field) return false;
    const value = field.value.trim();
    const rawValue = field.value;

    if (!value || (field.id === 'name' && !/[A-Za-z]/.test(rawValue))) {
        const label = field.labels?.[0]?.textContent?.split('*')[0].trim() || 'This field';
        showError(field, `${label} is required`);
        updateFieldStatus(field, false);
        return false;
    }

    if (!field.checkValidity()) {
        const validator = fieldValidators[field.id] || fieldValidators[field.type];
        const customMessage = validator ? validator(field.value) : null;
        const message = customMessage || 'Please enter a valid value';
        showError(field, message);
        updateFieldStatus(field, false);
        return false;
    }

    clearError(field);
    updateFieldStatus(field, true);
    return true;
};

