const messageField = document.getElementById('message');
const messageCounter = document.getElementById('message-counter');

const updateMessageCounter = () => {
    if (messageCounter) {
        const length = messageField.value.length;
        const remaining = 1000 - length;
        const percentage = Math.round((length / 1000) * 100);
        messageCounter.textContent = `${length} / 1000 characters (${percentage}%)${remaining < 100 && remaining > 0 ? ` - ${remaining} remaining` : ''}`;
        messageCounter.classList.remove('warning', 'critical');
        if (remaining < 50) {
            messageCounter.classList.add('critical');
        } else if (remaining < 100) {
            messageCounter.classList.add('warning');
        }
    }
};

if (messageField && messageCounter) {
    updateMessageCounter();
    messageField.addEventListener('input', updateMessageCounter);
}

